let selectedMatchFriends = [];
window.openMatchFriendSelection = function(isStriker) {
    selectedMatchFriends = [];
    const modal = document.getElementById('p2-skill-modal');
    const title = document.getElementById('skill-modal-title');
    const body = document.getElementById('skill-modal-body');

    modal.classList.remove('hidden');
    title.textContent = 'SELECCIONA 3 ALIADOS PARA EL PARTIDO';

    const knownNPCs = Object.keys(p2Relationships);
    const friends = knownNPCs.map(id => {
        return {
            id: id,
            npc: p2StratumPlayers.find(p => p.id === id),
            data: p2Relationships[id]
        };
    }).filter(f => f.npc);

    if (friends.length === 0) {
        body.innerHTML = `
            <div style="text-align:center; color:#aaa; padding:20px;">No conoces a nadie todavía. Jugarás con desconocidos.</div>
            <div style="text-align:center; margin-top:20px;">
                <button class="p2-action-btn" onclick="document.getElementById('p2-skill-modal').classList.add('hidden'); startMatch(${isStriker}, [])" style="border-color:#00ff00; color:#00ff00;"><span>IR AL PARTIDO</span></button>
            </div>
        `;
        return;
    }

    const renderFriendList = () => {
        body.innerHTML = '';
        body.style.maxHeight = '500px';
        body.style.overflowY = 'auto';

        const countDiv = document.createElement('div');
        countDiv.style.cssText = 'text-align:center; font-family:"Bangers"; font-size:1.4rem; color:#00ffcc; margin-bottom:10px;';
        countDiv.textContent = `SELECCIONADOS: ${selectedMatchFriends.length} / 3`;
        body.appendChild(countDiv);

        const grid = document.createElement('div');
        grid.style.cssText = 'display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:20px;';

        friends.forEach(f => {
            const friendVal = typeof f.data === 'object' ? (f.data.friendship || 0) : f.data;
            const isSelected = selectedMatchFriends.includes(f.id);
            const grl = Math.floor(f.npc.p2Rating || calcRating(f.npc.rating));
            const bonusGRL = Math.floor(grl * (friendVal / 1000));

            const card = document.createElement('div');
            card.style.cssText = `display:flex; align-items:center; gap:10px; padding:10px; border-radius:8px; cursor:pointer; border:2px solid ${isSelected ? '#00ffcc' : '#333'}; background:${isSelected ? 'rgba(0,255,204,0.1)' : 'rgba(0,0,0,0.5)'}; transition:all 0.2s;`;

            card.innerHTML = `
                <img src="${f.npc.image}" style="width:50px; height:50px; object-fit:contain; border-radius:50%; background:#111;">
                <div style="flex:1;">
                    <div style="font-weight:bold; font-size:1rem;">${f.npc.name}</div>
                    <div style="font-size:0.85rem; color:#ffd700;">GRL ${grl} <span style="color:#00ffcc;">(+${bonusGRL})</span></div>
                    <div style="font-size:0.8rem; color:#aaa;">Amistad: ${friendVal}%</div>
                </div>
            `;

            card.onclick = () => {
                if (isSelected) {
                    selectedMatchFriends = selectedMatchFriends.filter(id => id !== f.id);
                    renderFriendList();
                } else if (selectedMatchFriends.length < 3) {
                    selectedMatchFriends.push(f.id);
                    renderFriendList();
                }
            };

            grid.appendChild(card);
        });
        body.appendChild(grid);

        const btnDiv = document.createElement('div');
        btnDiv.style.cssText = 'text-align:center; margin-top:10px;';
        btnDiv.innerHTML = `<button class="p2-action-btn" onclick="document.getElementById('p2-skill-modal').classList.add('hidden'); startMatch(${isStriker}, selectedMatchFriends)" style="border-color:#00ff00; color:#00ff00;"><span>⚽ JUGAR PARTIDO</span></button>`;
        body.appendChild(btnDiv);
    };

    renderFriendList();
};

window.tryPersuade = function(stat) {
    const val = p2Stats[stat];
    const chat = document.getElementById('tactics-chat');
    const opts = document.getElementById('tactics-options');

    chat.innerHTML += `<div class="tactics-msg" style="border-left-color:#00ff00;"><b>Tú:</b> Confíad en mí, lo haré bien.</div>`;

    setTimeout(() => {
        if (val >= 65 || Math.random() > 0.5) { // Win negotiation
            chat.innerHTML += `<div class="tactics-msg"><b>Compañeros:</b> Está bien, rotaremos posiciones. ¡Tú serás nuestro DC titular los primeros minutos!</div>`;
            opts.innerHTML = `<button class="p2-action-btn" onclick="openMatchFriendSelection(true)" style="border-color:#00ff00; color:#00ff00;"><span>⚽ ELEGIR AMIGOS PARA EL PARTIDO</span></button>`;
        } else {
            chat.innerHTML += `<div class="tactics-msg"><b>Compañeros:</b> No nos convences. Jugarás de defensa o te quedas en el banquillo.</div>`;
            opts.innerHTML = `<button class="p2-action-btn" onclick="openMatchFriendSelection(false)" style="border-color:#ff4444; color:#ff4444;"><span>⚽ ELEGIR AMIGOS PARA EL PARTIDO</span></button>`;
        }
    }, 1000);
};

window.startMatch = function(isStriker, friendIds = []) {
    showNotification('Simulando partido de 90 minutos...', 'info', 4000);

    // Calculate Win Probability dynamically based on Friendship
    let teamBonus = 0;
    friendIds.forEach(id => {
        const npc = p2StratumPlayers.find(p => p.id === id);
        if (npc) {
            const data = p2Relationships[id];
            const friendVal = typeof data === 'object' ? (data.friendship || 0) : data;
            const grl = Math.floor(npc.p2Rating || calcRating(npc.rating));
            teamBonus += (grl + Math.floor(grl * (friendVal / 1000))); // Base GRL + Up to 10% bonus
        }
    });

    const myGRL = calcOVR();
    const ourStrength = myGRL + teamBonus + (3 - friendIds.length) * 65; // Desconocidos asumen GRL 65
    const enemyStrength = 75 + (70 * 3); // Dificultad base enemiga (aprox 285)

    // Min prob 25%, max prob 90%
    const winProbability = Math.max(0.25, Math.min(0.90, ourStrength / (ourStrength + enemyStrength)));
    const win = Math.random() < winProbability;

    // Simulate Match result
    const goalsScored = isStriker ? Math.floor(Math.random() * 4) + 1 : Math.floor(Math.random() * 2);
    p2Stats.goals += goalsScored;

    const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
    if (win) {
        myTeam.w++;
        myTeam.pts += 3;
        showNotification(`¡VICTORIA! Probabilidad era ${Math.floor(winProbability*100)}%. Has marcado ${goalsScored} goles. (Goles Totales: ${p2Stats.goals})`, 'success', 5000);
    } else {
        myTeam.l++;
        showNotification(`DERROTA... Probabilidad era ${Math.floor(winProbability*100)}%. Has marcado ${goalsScored} goles. (Goles Totales: ${p2Stats.goals})`, 'error', 5000);
    }

    // Simulate other matches
    p2League.forEach(t => {
        if (!t.name.includes("Tu Equipo")) {
            t.w += Math.floor(Math.random() * 2);
            t.pts = (t.w * 3) + t.d;
        }
    });

    // Simulate scorers
    p2TopScorers.forEach(s => s.g += Math.floor(Math.random() * 3));

    // Award Match EXP and open interactive distributor
    const matchXp = 250 + (win ? 200 : 50) + (goalsScored * 75);
    const summaryText = win 
        ? `¡VICTORIA! Has ganado +${matchXp} EXP total y marcado ${goalsScored} goles.` 
        : `DERROTA... Aún así ganaste +${matchXp} EXP total por tu esfuerzo y ${goalsScored} goles.`;
    openMatchXpDistributor(matchXp, summaryText);
};

