    p2RoomBody.innerHTML = '';

    // Spawn 1 random NPC
    const roomNPCs = p2StratumPlayers.filter(p => !p2Stats.npcInteractionsToday.includes(p.id));
    const npc = roomNPCs.length > 0 ? roomNPCs[Math.floor(Math.random() * roomNPCs.length)] : null;

    if (npc) {
        // NPC Body (Sincabeza)
        const bodyDiv = document.createElement('div');
        bodyDiv.className = 'p2-scene-overlay';
        bodyDiv.style.cssText = 'left:45%; bottom:5%; width:200px; height:300px; cursor:pointer; z-index:20;';
        bodyDiv.innerHTML = `<img src="${basePath}Sincabeza.png" draggable="false" style="width:100%; height:100%; object-fit:contain; transition: transform 0.2s, filter 0.2s;">`;
        p2LobbyScreen.appendChild(bodyDiv);

        // NPC Head (Behind the body)
        const headDiv = document.createElement('div');
        headDiv.className = 'p2-scene-overlay';
        headDiv.style.cssText = `left:48.5%; bottom:26%; width:90px; height:90px; cursor:pointer; z-index:15;`;
        headDiv.innerHTML = `<img src="${npc.image}" draggable="false" style="width:100%; height:100%; object-fit:contain; transition: transform 0.2s, filter 0.2s;">`;
        p2LobbyScreen.appendChild(headDiv);

        bodyDiv.onclick = headDiv.onclick = () => { openDialogue(npc); };

        const bImg = bodyDiv.querySelector('img');
        const hImg = headDiv.querySelector('img');
        const syncHover = () => {
            bImg.style.transform = 'scale(1.05)'; bImg.style.filter = 'brightness(1.3)';
            hImg.style.transform = 'scale(1.05)'; hImg.style.filter = 'brightness(1.3)';
        };
        const syncLeave = () => {
            bImg.style.transform = 'scale(1)'; bImg.style.filter = 'brightness(1)';
            hImg.style.transform = 'scale(1)'; hImg.style.filter = 'brightness(1)';
        };
        bodyDiv.onmouseenter = headDiv.onmouseenter = syncHover;
        bodyDiv.onmouseleave = headDiv.onmouseleave = syncLeave;
    }

    // Icon ChutPrac (Shooting)
    const btnChut = document.createElement('div');
    btnChut.className = 'p2-scene-overlay';
    btnChut.style.cssText = 'left:20%; top:50%; transform:translate(-50%,-50%); width:120px; height:120px; cursor:pointer; z-index:10;';
    btnChut.innerHTML = `<img src="${basePath}ChutPrac.png" draggable="false" style="width:100%; height:100%; object-fit:contain; filter:drop-shadow(0 0 10px #ff007f); transition: transform 0.2s;">`;
    btnChut.onclick = () => { startChutMinigame(); };
    btnChut.onmouseenter = () => btnChut.querySelector('img').style.transform = 'scale(1.1)';
    btnChut.onmouseleave = () => btnChut.querySelector('img').style.transform = 'scale(1)';
    p2LobbyScreen.appendChild(btnChut);

    // Icon Conos (Dribbling)
