let time = 30;
let score = 0;
let speed = 0.012;
let obstacles = [];
let isGameOver = false;
let spawnTimer = 0;
let spawnRate = 60;

setTimeout(() => {
    const gameLoop = setInterval(() => {
        if (isGameOver) return;
    spawnTimer++;
    if (spawnTimer >= spawnRate) {
        spawnTimer = 0;
        let num = Math.random() > 0.8 ? 2 : 1;
        let avail = [0, 1, 2];
        for(let i=0; i<num; i++) {
            let r = Math.floor(Math.random() * avail.length);
            let lane = avail.splice(r, 1)[0];
            let obs = document.createElement('div');
            obs.style.cssText = `position:absolute; top:20%; width:80px; height:80px; transform:scale(0); transform-origin:bottom center;`;
            obs.innerHTML = `<img src="assets/Historia/Habitaciones/Barrera.png" style="width:100%; height:100%; object-fit:contain;">`;
            gameArea.appendChild(obs);
            obstacles.push({ el: obs, z: 0, lane: lane, passed: false });
        }
        if (spawnRate > 20) spawnRate -= 2;
        speed += 0.0005;
    }

    let maxOffsetX = gameArea.offsetWidth * 0.35;
    let horizonY = 50;
    let playerY = gameArea.offsetHeight - 100;

    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.z += speed;

        let scale = obs.z * obs.z; // Non-linear for better perspective
        let targetY = horizonY + (playerY - horizonY) * obs.z;
        let currentOffsetX = maxOffsetX * (obs.lane - 1) * obs.z;

        obs.el.style.left = `calc(50% - 40px + ${currentOffsetX}px)`;
        obs.el.style.top = `${targetY}px`;
        obs.el.style.transform = `scale(${Math.max(0, scale)})`;
        obs.el.style.zIndex = Math.floor(obs.z * 100);

        // Collision
        if (obs.lane === currentLane && obs.z > 0.85 && obs.z < 1.15) {
            endGame(false);
            break;
        }
        if (obs.z > 1.15 && !obs.passed) {
            obs.passed = true;
            score++;
            scoreEl.innerText = `Esquivados: ${score}`;
        }
        if (obs.z > 1.5) {
            obs.el.remove();
            obstacles.splice(i, 1);
        }
    }
}, 1000/60);

