window.tacticsMakeChoice = function(shift) {
    window.tacticsDetroitState.affinity += shift;
    window.tacticsDetroitState.affinity = Math.max(0, Math.min(100, window.tacticsDetroitState.affinity));
    window.tacticsDetroitState.turn++;
    updateTacticsDetroitUI();
};

window.updateTacticsDetroitUI = function() {
    const state = window.tacticsDetroitState;
    const cursor = document.getElementById('detroit-cursor');
    const text = document.getElementById('detroit-text');
    const options = document.getElementById('detroit-options');

    if (!cursor) return;

    // Visual update
    cursor.style.left = `${state.affinity}%`;

    if (state.turn === 0) {
        text.innerHTML = `<b>Compañeros:</b> Es día de partido. ¿En qué posición vas a jugar hoy?`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-37.5)"><span>"Seré el muro atrás." (DEF)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-12.5)"><span>"Repartiré el juego." (MED)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(12.5)"><span>"¡Yo marcaré los goles!" (DEL)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(37.5)"><span>"Yo me pongo los guantes." (POR)</span></button>
        `;
    } else if (state.turn === 1) {
        text.innerHTML = `<b>Compañeros:</b> ¡Pero si siempre jugamos así y nos meten goles! Necesitamos cambiar la estrategia.`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-15)"><span>"Pues me quedo más atrás para asegurar." (Retrasar línea)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(15)"><span>"La mejor defensa es un buen ataque." (Adelantar línea)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(0)"><span>"Confiad en mí, todo saldrá bien." (Mantener táctica)</span></button>
        `;
    } else if (state.turn === 2) {
        let posName = "Defensa";
        if(state.affinity >= 25) posName = "Centrocampista";
        if(state.affinity >= 50) posName = "Delantero";
        if(state.affinity >= 75) posName = "Portero";

        text.innerHTML = `<b>Compañeros:</b> De acuerdo... parece que tu puesto natural hoy es de ${posName}. ¿Seguro?`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-10)"><span>"No, mejor aseguro atrás." (Más defensivo)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(0)"><span>"¡Completamente seguro!" (Confirmar puesto)</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(10)"><span>"Voy a arriesgar un poco más." (Más ofensivo / Portero)</span></button>
        `;
    } else if (state.turn === 3) {
        let finalPos = 'DEF';
        if(state.affinity >= 25) finalPos = 'MED';
        if(state.affinity >= 50) finalPos = 'DEL';
        if(state.affinity >= 75) finalPos = 'POR';

        let posName = "Defensa";
        if(finalPos === 'MED') posName = "Centrocampista";
        if(finalPos === 'DEL') posName = "Delantero";
        if(finalPos === 'POR') posName = "Portero";

        text.innerHTML = `<b>Compañeros:</b> ¡Decidido! Jugarás como ${posName} hoy. ¡A por todas!`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="startMatch('${finalPos}')" style="border-color:#00e5ff; color:#00e5ff;"><span>⚽ SALTAR AL CAMPO</span></button>
        `;
    }
};

