window.tacticsMakeChoice = function(shiftAffinity, shiftTension) {
    const state = window.tacticsDetroitState;

    if (state.timerId) {
        clearInterval(state.timerId);
        state.timerId = null;
    }

    state.affinity += shiftAffinity;
    state.affinity = Math.max(0, Math.min(100, state.affinity));

    state.tension += shiftTension;
    state.tension = Math.max(0, Math.min(100, state.tension));

    if (state.tension >= 100 && state.turn < 5) {
        state.turn = 99;
    } else {
        state.turn++;
    }

    updateTacticsDetroitUI();
};

window.updateTacticsDetroitUI = function() {
    const state = window.tacticsDetroitState;
    const cursor = document.getElementById('detroit-cursor');
    const text = document.getElementById('detroit-text');
    const options = document.getElementById('detroit-options');
    const tensionBar = document.getElementById('detroit-tension-bar');
    const tensionVal = document.getElementById('detroit-tension-val');
    const pulse = document.getElementById('tactics-pulse');
    const timerBar = document.getElementById('detroit-timer-bar');

    if (!cursor) return;

    if (!document.getElementById('tactics-css')) {
        const style = document.createElement('style');
        style.id = 'tactics-css';
        style.innerHTML = `
            @keyframes tacticsPulse {
                0% { background: rgba(255,0,0,0.1); }
                100% { background: rgba(255,0,0,0.5); }
            }
        `;
        document.head.appendChild(style);
    }

    cursor.style.left = `${state.affinity}%`;
    tensionBar.style.width = `${state.tension}%`;
    tensionVal.innerText = `${Math.floor(state.tension)}%`;

    if (state.tension > 75) {
        pulse.style.animation = 'tacticsPulse 0.5s infinite alternate';
    } else {
        pulse.style.animation = 'none';
        pulse.style.background = 'rgba(255,0,0,0)';
    }

    if (state.turn < 5 && state.turn !== 99) {
        state.timeLeft = 7.0;
        timerBar.style.width = '100%';
        timerBar.style.background = '#fff';

        state.timerId = setInterval(() => {
            state.timeLeft -= 0.1;
            const pct = (state.timeLeft / 7.0) * 100;
            timerBar.style.width = `${pct}%`;

            if (pct < 30) timerBar.style.background = '#ff4444';
            else if (pct < 60) timerBar.style.background = '#ffaa00';

            if (state.timeLeft <= 0) {
                clearInterval(state.timerId);
                state.timerId = null;
                tacticsMakeChoice(-15, 20); // Penalty for silence
            }
        }, 100);
    } else {
        timerBar.style.width = '0%';
    }

    if (state.turn === 0) {
        text.innerHTML = `<b>Compañero 1:</b> Escucha, novato. Hoy juego yo de delantero centro. Tú ponte en la defensa y no estorbes.`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(20, 25)"><span>"Vas a chupar banquillo. El dorsal '9' es mío."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(10, 10)"><span>"Venga ya, si no le marcas ni al arcoíris. Yo voy arriba."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-15, -10)"><span>"Bueno, quizás pueda jugar un poco más atrasado..."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-35, -20)"><span>"Vale, jugaré en la defensa para que tú destaques."</span></button>
        `;
    } else if (state.turn === 1) {
        text.innerHTML = `<b>Compañero 2:</b> ¡Un momento! Si este crío juega arriba, no va a bajar a presionar. ¿Quién va a defender los contraataques?`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(15, 30)"><span>"La mejor defensa es marcar cinco goles, inútil."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(0, -15)"><span>"Tranquilos, prometo que bajaré a defender si es necesario."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-20, -10)"><span>"Vale, entonces jugaré en el medio para equilibrar."</span></button>
        `;
    } else if (state.turn === 2) {
        text.innerHTML = `<b>Compañero 3:</b> No me fío un pelo de él. Sus números físicos son una basura. Nos van a aplastar.`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(15, 30)"><span>"Mis piernas valen más que todo tu linaje. Apártate."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(5, 5)"><span>"El talento supera al físico, os lo demostraré hoy."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-20, -15)"><span>"Supongo que me quedaré atrás cerrando huecos entonces..."</span></button>
        `;
    } else if (state.turn === 3) {
        text.innerHTML = `<b>Compañero 1:</b> El míster cuenta conmigo para marcar. Dame una buena razón para dejarte mi puesto.`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(15, 35)"><span>"Porque yo soy la estrella de este equipo, no tú."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(5, -20)"><span>"Porque si me das asistencias, los dos saldremos ganando."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(-15, -15)"><span>"De acuerdo, jugaré en el medio y te daré pases."</span></button>
        `;
    } else if (state.turn === 4) {
        text.innerHTML = `<b>Compañeros:</b> ¡Esta es tu última oportunidad! ¿Qué te hace pensar que mereces ese puesto en el once?`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="tacticsMakeChoice(20, 20)"><span>"Porque soy el mejor y punto."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(0, -15)"><span>"Dejadme demostrarlo hoy. Si fallo, jugaré donde queráis mañana."</span></button>
            <button class="p2-action-btn" onclick="tacticsMakeChoice(30, -50)"><span>"Paso de vosotros. Me voy a la portería, haced el ridículo solos."</span></button>
        `;
    } else if (state.turn === 99) {
        text.innerHTML = `<b>Compañeros:</b> ¡SE ACABÓ! Estamos hartos de tu chulería. ¡Te vas a la portería castigado por listo!`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="startMatch('POR')" style="border-color:#ff4444; color:#ff4444;"><span>⚽ IR A LA PORTERÍA (Castigado)</span></button>
        `;
    } else if (state.turn === 5) {
        let finalPos = 'DEF';
        if(state.affinity >= 25) finalPos = 'MED';
        if(state.affinity >= 50) finalPos = 'DEL';
        if(state.affinity >= 75) finalPos = 'POR';

        let posName = "Defensa";
        if(finalPos === 'MED') posName = "Centrocampista";
        if(finalPos === 'DEL') posName = "Delantero";
        if(finalPos === 'POR') posName = "Portero";

        text.innerHTML = `<b>Compañeros:</b> De acuerdo... Jugarás de ${posName}. Pero como la cagues, te vas a enterar.`;
        options.innerHTML = `
            <button class="p2-action-btn" onclick="startMatch('${finalPos}')" style="border-color:#00e5ff; color:#00e5ff;"><span>⚽ SALTAR AL CAMPO</span></button>
        `;
    }
};

