    const timeDisplay = document.createElement('div');
    timeDisplay.innerText = "00:00";

    const scoreDisplay = document.createElement('div');
    scoreDisplay.innerText = "Goles Encajados: 0 | Paradas: 0";

    hud.appendChild(timeDisplay);
    hud.appendChild(scoreDisplay);
    engine.appendChild(hud);

    const flash = document.createElement('div');
    flash.style.cssText = 'position:absolute; top:0; left:0; width:100%; height:100%; background:#fff; opacity:0; z-index:120; pointer-events:none; transition:opacity 0.2s;';
    engine.appendChild(flash);

    // Guantes (Visuals)
    const gloves = document.createElement('img');
    gloves.src = 'assets/Match/Guantes.png';
    gloves.onerror = () => { gloves.style.display="none"; };
    gloves.style.cssText = 'position:absolute; bottom:-10%; left:50%; transform:translateX(-50%); width:300px; height:200px; object-fit:contain; z-index:125; transition:all 0.3s cubic-bezier(0.2, 0.8, 0.4, 1); filter:drop-shadow(0 10px 10px rgba(0,0,0,0.5));';
    engine.appendChild(gloves);

    // Controles UI
    const controls = document.createElement('div');
    controls.style.cssText = 'position:absolute; bottom:20px; left:50%; transform:translateX(-50%); display:flex; gap:15px; z-index:150;';

    function createBtn(id, text, icon) {
        const btn = document.createElement('div');
        btn.id = id;
        btn.innerHTML = `<span style="font-size:2rem; display:block;">${icon}</span><span style="font-size:0.8rem;">${text}</span>`;
        btn.style.cssText = 'width:80px; height:80px; background:rgba(0,0,0,0.7); border:2px solid #00e5ff; border-radius:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; color:#00e5ff; font-weight:bold; cursor:pointer; user-select:none; transition:all 0.1s; text-align:center;';
        btn.onmousedown = () => btn.style.transform = 'scale(0.9)';
        btn.onmouseup = () => btn.style.transform = 'scale(1)';
        return btn;
    }

    const btnLeft = createBtn('btn-gk-left', 'IZQUIERDA', '⬅️');
    const btnDown = createBtn('btn-gk-down', 'AGUANTAR', '⬇️');
    const btnUp = createBtn('btn-gk-up', 'PUÑOS', '⬆️');
    const btnRight = createBtn('btn-gk-right', 'DERECHA', '➡️');

    controls.appendChild(btnLeft);
    controls.appendChild(btnDown);
    controls.appendChild(btnUp);
    controls.appendChild(btnRight);
    engine.appendChild(controls);

    p2RoomBody.appendChild(engine);

    let minute = 0;
    let saves = 0;
    let goalsConceded = 0;
    let matchInterval = null;
    const highlightMinutes = [14, 31, 55, 78, 89]; // Added one more for variety

    // Control Logic
    let activeAction = null;
    let actionResolver = null;

    function triggerAction(action) {
        if (activeAction) return;
        activeAction = action;

        // Animate gloves
        if (action === 'LEFT') {
            gloves.style.transform = 'translate(-120%, -30%) rotate(-30deg)';
        } else if (action === 'RIGHT') {
            gloves.style.transform = 'translate(20%, -30%) rotate(30deg)';
        } else if (action === 'UP') {
            gloves.style.transform = 'translate(-50%, -80%) scale(1.2)';
        } else if (action === 'DOWN') {
            gloves.style.transform = 'translate(-50%, 0) scale(1.1)';
        }

        if (actionResolver) {
            actionResolver(action);
            actionResolver = null;
        }

        setTimeout(() => {
            gloves.style.transform = 'translateX(-50%)';
            activeAction = null;
        }, 600);
    }

    btnLeft.onclick = () => triggerAction('LEFT');
    btnRight.onclick = () => triggerAction('RIGHT');
    btnUp.onclick = () => triggerAction('UP');
    btnDown.onclick = () => triggerAction('DOWN');

    const keyHandler = (e) => {
        if (e.key === 'ArrowLeft') triggerAction('LEFT');
        if (e.key === 'ArrowRight') triggerAction('RIGHT');
        if (e.key === 'ArrowUp') triggerAction('UP');
        if (e.key === 'ArrowDown') triggerAction('DOWN');
    };
    window.addEventListener('keydown', keyHandler);

    function updateHUD() {
        timeDisplay.innerText = `${minute < 10 ? '0':''}${minute}:00`;
        scoreDisplay.innerText = `Goles Encajados: ${goalsConceded} | Paradas: ${saves}`;
    }

    function endMatch() {
        window.removeEventListener('keydown', keyHandler);
        engine.remove();

        const teamGoals = Math.floor(Math.random() * 3);
        const win = teamGoals > goalsConceded;

        const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
        if (myTeam) {
            if (win) { myTeam.w++; myTeam.pts += 3; }
            else if (teamGoals === goalsConceded) { myTeam.d++; myTeam.pts += 1; }
            else { myTeam.l++; }
        }

        p2League.forEach(t => {
            if (!t.name.includes("Tu Equipo")) {
                t.w += Math.floor(Math.random() * 2);
                t.pts = (t.w * 3) + t.d;
            }
        });

        const matchXp = 250 + (win ? 200 : (teamGoals === goalsConceded ? 100 : 50)) + (saves * 75);
        const resultTxt = win ? '¡VICTORIA!' : (teamGoals === goalsConceded ? 'EMPATE' : 'DERROTA...');

        showNotification(`${resultTxt} Resultado: ${teamGoals}-${goalsConceded}. Paradas: ${saves}`, win ? 'success' : (teamGoals===goalsConceded ? 'warning':'error'), 6000);

        setTimeout(() => {
            openMatchXpDistributor(matchXp, `${resultTxt} El equipo metió ${teamGoals} goles, encajaste ${goalsConceded} y paraste ${saves} tiros. XP Total: ${matchXp}`);
        }, 1000);
    }

    function startHighlight() {
        flash.style.opacity = '1';
        setTimeout(() => { flash.style.opacity = '0'; }, 200);

        const alertTxt = document.createElement('div');
        alertTxt.style.cssText = 'position:absolute; top:35%; left:50%; transform:translate(-50%,-50%); font-size:3rem; color:#ff4444; text-shadow:0 0 10px #000, 0 0 20px #ff0000; font-weight:bold; z-index:115; white-space:nowrap; animation: bounce 1s infinite;';
        alertTxt.innerText = "¡PELIGRO!";
        engine.appendChild(alertTxt);

        // 0=Lejano, 1=Mano a Mano, 2=Córner, 3=Penalti, 4=Falta
        const scenario = Math.floor(Math.random() * 5);

        setTimeout(() => {
            alertTxt.remove();
            playScenario(scenario);
        }, 1200);
    }

    function finishPlay(success, txtWin, txtLose) {
        if (success) {
            saves++; showNotification(txtWin, 'success', 2000);
        } else {
            goalsConceded++; showNotification(txtLose, 'error', 2000);
        }
        setTimeout(resumeMatch, 1000);
    }

    function playScenario(type) {
        let reactTime = 1600; 

        const ball = document.createElement('img');
        ball.src = 'assets/Match/Pelota.png';
        ball.onerror = () => { ball.style.display="none"; };
        ball.style.cssText = `position:absolute; top:50%; left:50%; width:20px; height:20px; z-index:120; transition: all ${reactTime}ms cubic-bezier(0.2, 0.8, 0.4, 1); filter:drop-shadow(0 0 10px #000); background:#fff; border-radius:50%; transform:translate(-50%,-50%);`;

        let resolved = false;
        let success = false;

        if (type === 0) {
            // TIRO LEJANO
            engine.appendChild(ball);
            const dirs = ['LEFT', 'RIGHT', 'DOWN'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            const hint = document.createElement('div');
            hint.style.cssText = 'position:absolute; width:100px; height:100px; border:2px dashed rgba(255,0,0,0.5); border-radius:50%; top:60%; transform:translate(-50%,-50%); z-index:115; animation:pulse 0.5s infinite;';
            if (correctDir === 'LEFT') hint.style.left = '25%';
            else if (correctDir === 'RIGHT') hint.style.left = '75%';
            else hint.style.left = '50%';

            setTimeout(() => engine.appendChild(hint), reactTime * 0.3);

            setTimeout(() => {
                ball.style.top = '60%';
                if (correctDir === 'LEFT') ball.style.left = '25%';
                else if (correctDir === 'RIGHT') ball.style.left = '75%';
                else ball.style.left = '50%';
                ball.style.width = '150px'; ball.style.height = '150px';
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) { success = true; ball.style.top = '-20%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                if (hint.parentNode) hint.remove();
                finishPlay(success, '¡PARADÓN!', '¡GOL DESDE LEJOS!');
                ball.remove();
            }, reactTime);

        } else if (type === 1) {
            // MANO A MANO
            engine.appendChild(ball);
            ball.style.transition = 'none';

            const rival = document.createElement('div');
            rival.style.cssText = 'position:absolute; top:45%; left:50%; transform:translateX(-50%); font-size:4rem; z-index:115;';
            rival.innerText = "🏃";
            engine.appendChild(rival);

            actionResolver = (act) => {
                resolved = true;
                if (act === 'DOWN') { success = true; } // Solo aguantar es correcto
            };

            setTimeout(() => {
                actionResolver = null;
                rival.remove();
                if (!resolved || !success) {
                    ball.style.transition = 'all 0.2s';
                    ball.style.top = '60%';
                    ball.style.left = Math.random() > 0.5 ? '20%' : '80%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }
                setTimeout(() => {
                    finishPlay(success, '¡BLOQUEO VITAL!', '¡GOL A BOCAJARRO!');
                    ball.remove();
                }, 200);
            }, reactTime * 0.8);

        } else if (type === 2) {
            // CÓRNER
            ball.style.top = '10%'; ball.style.left = '90%';
            engine.appendChild(ball);

            const helpTxt = document.createElement('div');
            helpTxt.innerText = "¡CÓRNER!";
            helpTxt.style.cssText = 'position:absolute; top:15%; left:50%; transform:translateX(-50%); color:#fff; font-size:2rem; font-weight:bold; z-index:115; text-shadow:0 0 5px #000;';
            engine.appendChild(helpTxt);

            setTimeout(() => {
                ball.style.top = '30%'; ball.style.left = '50%';
                ball.style.width = '100px'; ball.style.height = '100px';
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === 'UP') { success = true; ball.style.top = '-10%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                helpTxt.remove();
                if (success) {
                    finishPlay(true, '¡DESPEJE DE PUÑOS!', '');
                    ball.remove();
                } else {
                    showNotification('¡REMATAN DE CABEZA!', 'warning', 1000);
                    ball.style.transition = 'all 0.5s';
                    ball.style.top = '70%';
                    const side = Math.random() > 0.5 ? 'LEFT' : 'RIGHT';
                    ball.style.left = side === 'LEFT' ? '25%' : '75%';
                    ball.style.width = '150px'; ball.style.height = '150px';

                    let secondSuccess = false;
                    actionResolver = (act2) => {
                        if (act2 === side) secondSuccess = true;
                    };

                    setTimeout(() => {
                        actionResolver = null;
                        finishPlay(secondSuccess, '¡PARADA MILAGROSA!', '¡GOL DE CABEZA!');
                        ball.remove();
                    }, 600);
                }
            }, reactTime * 0.8);

        } else if (type === 3) {
            // PENALTI
            engine.appendChild(ball);
            ball.style.transition = 'none';

            const helpTxt = document.createElement('div');
            helpTxt.innerText = "¡PENALTI!";
            helpTxt.style.cssText = 'position:absolute; top:15%; left:50%; transform:translateX(-50%); color:#ff9900; font-size:2rem; font-weight:bold; z-index:115; text-shadow:0 0 5px #000;';
            engine.appendChild(helpTxt);

            const dirs = ['LEFT', 'RIGHT', 'DOWN'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) success = true;

                ball.style.transition = 'all 0.3s cubic-bezier(0,0,1,1)';
                if (correctDir === 'LEFT') ball.style.left = '25%';
                else if (correctDir === 'RIGHT') ball.style.left = '75%';
                ball.style.width = '150px'; ball.style.height = '150px';
                if (success) ball.style.top = '20%'; // Paradón
                else ball.style.top = '60%'; // Gol
            };

            setTimeout(() => {
                actionResolver = null;
                helpTxt.remove();
                if (!resolved) {
                    ball.style.transition = 'all 0.3s cubic-bezier(0,0,1,1)';
                    if (correctDir === 'LEFT') ball.style.left = '25%';
                    else if (correctDir === 'RIGHT') ball.style.left = '75%';
                    ball.style.top = '60%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }
                setTimeout(() => {
                    finishPlay(success, '¡PARÓ EL PENALTI!', '¡GOL DE PENALTI!');
                    ball.remove();
                }, 400);
            }, reactTime);

        } else if (type === 4) {
            // FALTA (Curva)
            ball.style.top = '40%';
            engine.appendChild(ball);

            const barrera = document.createElement('div');
            barrera.style.cssText = 'position:absolute; top:45%; left:45%; width:100px; height:80px; background:rgba(255,0,0,0.5); border:2px solid red; border-radius:5px; z-index:115; color:#fff; display:flex; align-items:center; justify-content:center;';
            barrera.innerText = "BARRERA";
            engine.appendChild(barrera);

            const dirs = ['LEFT', 'RIGHT'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            setTimeout(() => {
                ball.style.transition = `all ${reactTime*0.4}ms cubic-bezier(0.1, 0.8, 0.5, 1)`;
                ball.style.top = '15%'; 
                if (correctDir === 'LEFT') ball.style.left = '70%'; 
                else ball.style.left = '30%';
                ball.style.width = '60px'; ball.style.height = '60px';

                setTimeout(() => {
                    ball.style.transition = `all ${reactTime*0.6}ms cubic-bezier(0.5, 0, 0.9, 0.2)`;
                    ball.style.top = '60%';
                    if (correctDir === 'LEFT') ball.style.left = '20%'; 
                    else ball.style.left = '80%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }, reactTime*0.4);
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) { success = true; ball.style.top = '10%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                barrera.remove();
                finishPlay(success, '¡VUELO ESPECTACULAR!', '¡GOLAZO DE FALTA!');
                ball.remove();
            }, reactTime);
        }
    }

    function resumeMatch() {
        updateHUD();
        matchInterval = setInterval(() => {
            minute++;
            updateHUD();

            if (highlightMinutes.includes(minute)) {
                clearInterval(matchInterval);
                startHighlight();
            } else if (minute >= 90) {
                clearInterval(matchInterval);
                endMatch();
            }
        }, 80); // 1 minuto = 80ms
    }

    // Iniciar
    resumeMatch();
};

