        const ball = document.createElement('img');
        ball.src = 'assets/Match/Pelota.png';
        ball.onerror = () => { ball.style.display="none"; };
        ball.style.cssText = `position:absolute; top:50%; left:50%; width:20px; height:20px; z-index:120; transition: all ${reactTime}ms cubic-bezier(0.2, 0.8, 0.4, 1); filter:drop-shadow(0 0 10px #000); background:#fff; border-radius:50%; transform:translate(-50%,-50%);`;

        let resolved = false;
        let success = false;

        if (type === 0) {
            // TIRO LEJANO
            engine.appendChild(ball);
            const dirs = ['LEFT', 'RIGHT', 'DOWN'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            const hint = document.createElement('div');
            hint.style.cssText = 'position:absolute; width:100px; height:100px; border:2px dashed rgba(255,0,0,0.5); border-radius:50%; top:60%; transform:translate(-50%,-50%); z-index:115; animation:pulse 0.5s infinite;';
            if (correctDir === 'LEFT') hint.style.left = '25%';
            else if (correctDir === 'RIGHT') hint.style.left = '75%';
            else hint.style.left = '50%';

            setTimeout(() => engine.appendChild(hint), reactTime * 0.3);

            setTimeout(() => {
                ball.style.top = '60%';
                if (correctDir === 'LEFT') ball.style.left = '25%';
                else if (correctDir === 'RIGHT') ball.style.left = '75%';
                else ball.style.left = '50%';
                ball.style.width = '150px'; ball.style.height = '150px';
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) { success = true; ball.style.top = '-20%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                if (hint.parentNode) hint.remove();
                finishPlay(success, '¡PARADÓN!', '¡GOL DESDE LEJOS!');
                ball.remove();
            }, reactTime);

        } else if (type === 1) {
            // MANO A MANO
            engine.appendChild(ball);
            ball.style.transition = 'none';

            const rival = document.createElement('div');
            rival.style.cssText = 'position:absolute; top:45%; left:50%; transform:translateX(-50%); font-size:4rem; z-index:115;';
            rival.innerText = "🏃";
            engine.appendChild(rival);

            actionResolver = (act) => {
                resolved = true;
                if (act === 'DOWN') { success = true; } // Solo aguantar es correcto
            };

            setTimeout(() => {
                actionResolver = null;
                rival.remove();
                if (!resolved || !success) {
                    ball.style.transition = 'all 0.2s';
                    ball.style.top = '60%';
                    ball.style.left = Math.random() > 0.5 ? '20%' : '80%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }
                setTimeout(() => {
                    finishPlay(success, '¡BLOQUEO VITAL!', '¡GOL A BOCAJARRO!');
                    ball.remove();
                }, 200);
            }, reactTime * 0.8);

        } else if (type === 2) {
            // CÓRNER
            ball.style.top = '10%'; ball.style.left = '90%';
            engine.appendChild(ball);

            const helpTxt = document.createElement('div');
            helpTxt.innerText = "¡CÓRNER!";
            helpTxt.style.cssText = 'position:absolute; top:15%; left:50%; transform:translateX(-50%); color:#fff; font-size:2rem; font-weight:bold; z-index:115; text-shadow:0 0 5px #000;';
            engine.appendChild(helpTxt);

            setTimeout(() => {
                ball.style.top = '30%'; ball.style.left = '50%';
                ball.style.width = '100px'; ball.style.height = '100px';
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === 'UP') { success = true; ball.style.top = '-10%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                helpTxt.remove();
                if (success) {
                    finishPlay(true, '¡DESPEJE DE PUÑOS!', '');
                    ball.remove();
                } else {
                    showNotification('¡REMATAN DE CABEZA!', 'warning', 1000);
                    ball.style.transition = 'all 0.5s';
                    ball.style.top = '70%';
                    const side = Math.random() > 0.5 ? 'LEFT' : 'RIGHT';
                    ball.style.left = side === 'LEFT' ? '25%' : '75%';
                    ball.style.width = '150px'; ball.style.height = '150px';

                    let secondSuccess = false;
                    actionResolver = (act2) => {
                        if (act2 === side) secondSuccess = true;
                    };

                    setTimeout(() => {
                        actionResolver = null;
                        finishPlay(secondSuccess, '¡PARADA MILAGROSA!', '¡GOL DE CABEZA!');
                        ball.remove();
                    }, 600);
                }
            }, reactTime * 0.8);

        } else if (type === 3) {
            // PENALTI
            engine.appendChild(ball);
            ball.style.transition = 'none';

            const helpTxt = document.createElement('div');
            helpTxt.innerText = "¡PENALTI!";
            helpTxt.style.cssText = 'position:absolute; top:15%; left:50%; transform:translateX(-50%); color:#ff9900; font-size:2rem; font-weight:bold; z-index:115; text-shadow:0 0 5px #000;';
            engine.appendChild(helpTxt);

            const dirs = ['LEFT', 'RIGHT', 'DOWN'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) success = true;

                ball.style.transition = 'all 0.3s cubic-bezier(0,0,1,1)';
                if (correctDir === 'LEFT') ball.style.left = '25%';
                else if (correctDir === 'RIGHT') ball.style.left = '75%';
                ball.style.width = '150px'; ball.style.height = '150px';
                if (success) ball.style.top = '20%'; // Paradón
                else ball.style.top = '60%'; // Gol
            };

            setTimeout(() => {
                actionResolver = null;
                helpTxt.remove();
                if (!resolved) {
                    ball.style.transition = 'all 0.3s cubic-bezier(0,0,1,1)';
                    if (correctDir === 'LEFT') ball.style.left = '25%';
                    else if (correctDir === 'RIGHT') ball.style.left = '75%';
                    ball.style.top = '60%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }
                setTimeout(() => {
                    finishPlay(success, '¡PARÓ EL PENALTI!', '¡GOL DE PENALTI!');
                    ball.remove();
                }, 400);
            }, reactTime);

        } else if (type === 4) {
            // FALTA (Curva)
            ball.style.top = '40%';
            engine.appendChild(ball);

            const barrera = document.createElement('div');
            barrera.style.cssText = 'position:absolute; top:45%; left:45%; width:100px; height:80px; background:rgba(255,0,0,0.5); border:2px solid red; border-radius:5px; z-index:115; color:#fff; display:flex; align-items:center; justify-content:center;';
            barrera.innerText = "BARRERA";
            engine.appendChild(barrera);

            const dirs = ['LEFT', 'RIGHT'];
            const correctDir = dirs[Math.floor(Math.random() * dirs.length)];

            setTimeout(() => {
                ball.style.transition = `all ${reactTime*0.4}ms cubic-bezier(0.1, 0.8, 0.5, 1)`;
                ball.style.top = '15%'; 
                if (correctDir === 'LEFT') ball.style.left = '70%'; 
                else ball.style.left = '30%';
                ball.style.width = '60px'; ball.style.height = '60px';

                setTimeout(() => {
                    ball.style.transition = `all ${reactTime*0.6}ms cubic-bezier(0.5, 0, 0.9, 0.2)`;
                    ball.style.top = '60%';
                    if (correctDir === 'LEFT') ball.style.left = '20%'; 
                    else ball.style.left = '80%';
                    ball.style.width = '150px'; ball.style.height = '150px';
                }, reactTime*0.4);
            }, 50);

            actionResolver = (act) => {
                resolved = true;
                if (act === correctDir) { success = true; ball.style.top = '10%'; }
            };

            setTimeout(() => {
                actionResolver = null;
                barrera.remove();
                finishPlay(success, '¡VUELO ESPECTACULAR!', '¡GOLAZO DE FALTA!');
                ball.remove();
            }, reactTime);
        }
    }

    function resumeMatch() {
        updateHUD();
        matchInterval = setInterval(() => {
            minute++;
            updateHUD();

            if (highlightMinutes.includes(minute)) {
                clearInterval(matchInterval);
                startHighlight();
            } else if (minute >= 90) {
                clearInterval(matchInterval);
                endMatch();
            }
        }, 80); // 1 minuto = 80ms
    }

