window.startMatch = function(position) {

    // Remove Detroit UI if it exists
    const detroitUI = document.getElementById('tactics-detroit-overlay');
    if (detroitUI) detroitUI.remove();

    const teammates = p2StratumPlayers.slice(0, 10);

    let teamStrength = 0;
    teammates.forEach(npc => {
        let friendVal = 0;
        if (p2Relationships[npc.id]) {
            const data = p2Relationships[npc.id];
            friendVal = typeof data === 'object' ? (data.friendship || 0) : data;
        }
        const grl = Math.floor(npc.p2Rating || calcRating(npc.rating));
        teamStrength += (grl + Math.floor(grl * (friendVal / 1000)));
    });

    const myGRL = calcOVR();
    const ourStrength = myGRL + teamStrength;
    const enemyStrength = 75 * 11;

    const winProbability = Math.max(0.25, Math.min(0.90, ourStrength / (ourStrength + enemyStrength)));
    const win = Math.random() < winProbability;

    // Call the Pre-Match VS Formation Screen instead of simulating immediately
    showFormationScreen(position, ourStrength, enemyStrength, winProbability, win, teammates, null);
};

window.showFormationScreen = function(position, ourStrength, enemyStrength, winProbability, win, teammates, matchContext) {
    p2RoomBody.innerHTML = '';

    const container = document.createElement('div');
    container.style.cssText = 'position:absolute; top:0; left:0; width:100%; height:100%; background:#1b5e20; z-index:100; font-family:"Nunito",sans-serif; overflow:hidden; display:flex; flex-direction:column; align-items:center;';

    const title = document.createElement('h2');
    title.innerText = 'TU EQUIPO';
    title.style.cssText = 'color:#fff; text-shadow:0 0 5px #000; font-family:"Bangers"; font-size:3rem; margin-top:20px;';
    container.appendChild(title);

    const pitch = document.createElement('div');
    pitch.style.cssText = 'position:relative; width:80%; max-width:800px; height:65%; border:2px solid rgba(255,255,255,0.5); margin-top:20px; border-radius:10px; background:repeating-linear-gradient(0deg, transparent, transparent 10%, rgba(255,255,255,0.05) 10%, rgba(255,255,255,0.05) 20%);';

    const centerLine = document.createElement('div');
    centerLine.style.cssText = 'position:absolute; top:50%; left:0; width:100%; height:2px; background:rgba(255,255,255,0.5);';
    pitch.appendChild(centerLine);

    const centerCircle = document.createElement('div');
    centerCircle.style.cssText = 'position:absolute; top:50%; left:50%; width:100px; height:100px; border:2px solid rgba(255,255,255,0.5); border-radius:50%; transform:translate(-50%, -50%);';
    pitch.appendChild(centerCircle);

    let availableSpots = [
        {top:'90%', left:'50%', pos:'POR'},
        {top:'70%', left:'20%', pos:'DEF'}, {top:'70%', left:'40%', pos:'DEF'}, {top:'70%', left:'60%', pos:'DEF'}, {top:'70%', left:'80%', pos:'DEF'},
        {top:'45%', left:'30%', pos:'MED'}, {top:'45%', left:'50%', pos:'MED'}, {top:'45%', left:'70%', pos:'MED'},
        {top:'20%', left:'30%', pos:'DEL'}, {top:'20%', left:'50%', pos:'DEL'}, {top:'20%', left:'70%', pos:'DEL'}
    ];

    let userSpotIndex = availableSpots.findIndex(s => s.pos === position);
    if(userSpotIndex === -1) userSpotIndex = 0;
    let userSpot = availableSpots.splice(userSpotIndex, 1)[0];

    const drawPlayer = (spot, name, iconUrl, color, isUser) => {
        const p = document.createElement('div');
        p.style.cssText = `position:absolute; top:${spot.top}; left:${spot.left}; transform:translate(-50%, -50%); display:flex; flex-direction:column; align-items:center; z-index:2; transition: all 0.5s; opacity:0; transform:translate(-50%, -30%) scale(0.8);`;

        const img = document.createElement('img');
        img.src = iconUrl;
        img.onerror = () => { img.src = 'assets/NPC_Default.png'; };
        img.style.cssText = `width:50px; height:50px; border-radius:50%; border:2px solid ${color}; background:#000; box-shadow:0 0 10px ${color}; object-fit:cover;`;
        if(isUser) {
            img.style.width = '70px'; img.style.height = '70px'; img.style.borderWidth = '3px'; img.style.boxShadow = '0 0 20px #ffd700';
        }

        const nameTag = document.createElement('div');
        nameTag.innerText = name;
        nameTag.style.cssText = `background:rgba(0,0,0,0.8); color:#fff; font-size:0.8rem; padding:2px 5px; border-radius:4px; margin-top:5px; font-weight:bold; white-space:nowrap; border:1px solid ${color};`;

        const posTag = document.createElement('div');
        posTag.innerText = spot.pos;
        posTag.style.cssText = `background:${color}; color:#fff; font-size:0.6rem; padding:1px 3px; border-radius:2px; margin-top:2px; font-weight:bold;`;

        p.appendChild(img);
        p.appendChild(nameTag);
        p.appendChild(posTag);
        pitch.appendChild(p);

        setTimeout(() => {
            p.style.opacity = '1';
            p.style.transform = 'translate(-50%, -50%) scale(1)';
        }, 100 + (Math.random() * 500));
    };

    drawPlayer(userSpot, p2Stats.name || 'TÚ', p2Stats.avatar || 'assets/Isagi.png', '#ffd700', true);

    teammates.forEach((npc, i) => {
        if (i < availableSpots.length) {
            let spot = availableSpots[i];
            drawPlayer(spot, npc.name, npc.img || 'assets/NPC_Default.png', '#00e5ff', false);
        }
    });

    container.appendChild(pitch);

    const nextBtn = document.createElement('button');
    nextBtn.className = 'p2-action-btn';
    nextBtn.innerText = 'Siguiente';
    nextBtn.style.marginTop = '20px';
    nextBtn.style.padding = '15px 40px';
    container.appendChild(nextBtn);

    p2RoomBody.appendChild(container);

    nextBtn.onclick = () => {
        title.innerText = 'EQUIPO RIVAL';
        title.style.color = '#ff4444';
        pitch.innerHTML = ''; 
        pitch.appendChild(centerLine);
        pitch.appendChild(centerCircle);

        let enemySpots = [
            {top:'10%', left:'50%', pos:'POR'},
            {top:'30%', left:'20%', pos:'DEF'}, {top:'30%', left:'40%', pos:'DEF'}, {top:'30%', left:'60%', pos:'DEF'}, {top:'30%', left:'80%', pos:'DEF'},
            {top:'55%', left:'30%', pos:'MED'}, {top:'55%', left:'50%', pos:'MED'}, {top:'55%', left:'70%', pos:'MED'},
            {top:'80%', left:'30%', pos:'DEL'}, {top:'80%', left:'50%', pos:'DEL'}, {top:'80%', left:'70%', pos:'DEL'}
        ];

        enemySpots.forEach((spot, i) => {
            drawPlayer(spot, `Rival ${i+1}`, 'assets/NPC_Default.png', '#ff4444', false);
        });

        nextBtn.innerText = '¡AL CAMPO!';
        nextBtn.style.borderColor = '#ff4444';
        nextBtn.style.color = '#ff4444';

        nextBtn.onclick = () => {
            container.style.transition = 'opacity 0.5s';
            container.style.opacity = '0';
            setTimeout(() => {
                if (position === 'POR') {
                    startGKMinigame(ourStrength, enemyStrength, winProbability);
                } else {
                    executeSimulation(position, win, matchContext);
                }
            }, 500);
        };
    };
};

function executeSimulation(position, win, context) {
    let goalsScored = 0;
    if (position === 'DEL' || position === true) {
        goalsScored = Math.floor(Math.random() * 4) + 1;
    } else if (position === 'MED') {
        goalsScored = Math.floor(Math.random() * 3);
    } else if (position === 'DEF' || position === false) {
        goalsScored = Math.floor(Math.random() * 2);
    } else if (position === 'POR') {
        goalsScored = 0;
    }

    p2Stats.goals += goalsScored;

    const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
