window.startMatch = function(position) {

    // Remove Detroit UI if it exists
    const detroitUI = document.getElementById('tactics-detroit-overlay');
    if (detroitUI) detroitUI.remove();

    // El equipo está formado por ti y los 10 primeros NPCs supervivientes del estrato
    const teammates = p2StratumPlayers.slice(0, 10);

    // Calculate Win Probability dynamically based on Friendship
    let teamStrength = 0;
    teammates.forEach(npc => {
        let friendVal = 0;
        if (p2Relationships[npc.id]) {
            const data = p2Relationships[npc.id];
            friendVal = typeof data === 'object' ? (data.friendship || 0) : data;
        }
        const grl = Math.floor(npc.p2Rating || calcRating(npc.rating));
        teamStrength += (grl + Math.floor(grl * (friendVal / 1000))); // Base GRL + Up to 10% bonus
    });

    const myGRL = calcOVR();
    const ourStrength = myGRL + teamStrength;
    const enemyStrength = 75 * 11; // Equipo rival tiene de media 75 de GRL por jugador aprox

    // Min prob 25%, max prob 90%
    const winProbability = Math.max(0.25, Math.min(0.90, ourStrength / (ourStrength + enemyStrength)));
    const win = Math.random() < winProbability;

    // Simulate Match result based on position
    if (position === 'POR') {
        startGKMinigame(ourStrength, enemyStrength, winProbability);
        return;
    }

    let goalsScored = 0;
    if (position === 'DEL' || position === true) {
        goalsScored = Math.floor(Math.random() * 4) + 1; // 1 to 4 goals
    } else if (position === 'MED') {
        goalsScored = Math.floor(Math.random() * 3);     // 0 to 2 goals
    } else if (position === 'DEF' || position === false) {
        goalsScored = Math.floor(Math.random() * 2);     // 0 to 1 goals
    } else if (position === 'POR') {
        goalsScored = 0;                                 // Goalkeeper scores 0
    }

    p2Stats.goals += goalsScored;

    const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
    if (win) {
        myTeam.w++;
        myTeam.pts += 3;
        showNotification(`¡VICTORIA! Probabilidad era ${Math.floor(winProbability*100)}%. Has marcado ${goalsScored} goles. (Goles Totales: ${p2Stats.goals})`, 'success', 5000);
    } else {
        myTeam.l++;
        showNotification(`DERROTA... Probabilidad era ${Math.floor(winProbability*100)}%. Has marcado ${goalsScored} goles. (Goles Totales: ${p2Stats.goals})`, 'error', 5000);
    }

    // Simulate other matches
    p2League.forEach(t => {
        if (!t.name.includes("Tu Equipo")) {
            t.w += Math.floor(Math.random() * 2);
            t.pts = (t.w * 3) + t.d;
        }
    });

    // Simulate scorers
    p2TopScorers.forEach(s => s.g += Math.floor(Math.random() * 3));

    // Award Match EXP and open interactive distributor
    const matchXp = 250 + (win ? 200 : 50) + (goalsScored * 75);
    const summaryText = win 
        ? `¡VICTORIA! Has ganado +${matchXp} EXP total y marcado ${goalsScored} goles.` 
        : `DERROTA... Aún así ganaste +${matchXp} EXP total por tu esfuerzo y ${goalsScored} goles.`;
    openMatchXpDistributor(matchXp, summaryText);
};

