    teammates.forEach((npc, i) => {
        if (i < allySpots.length) {
            drawPlayer(allySpots[i], npc.name, npc.image || 'assets/NPC_Default.png', '#00e5ff', false, 200 + i * 80);
        }
    });

    container.appendChild(pitch);

