    const nextBtn = document.createElement('button');
    nextBtn.className = 'p2-action-btn';
    nextBtn.innerHTML = '<span>Siguiente ▶</span>';
    nextBtn.style.cssText = 'margin:10px 0 15px 0; padding:12px 50px; font-size:1.2rem;';
    container.appendChild(nextBtn);

    p2LobbyScreen.appendChild(container);

    // Phase 2: Rival Team
    nextBtn.onclick = () => {
        teamName.innerText = 'EQUIPO RIVAL';
        teamName.style.color = '#ff4444';
        teamName.style.textShadow = '2px 2px 0 #000, -1px -1px 0 #000, 0 4px 10px rgba(255,0,0,0.5)';

        // Remove ALL ally players using class
        pitch.querySelectorAll('.formation-player').forEach(el => el.remove());

