    rightGlove.style.cssText = 'position:absolute; top:50%; left:55%; transform:translate(-50%, -50%); width:180px; height:180px; object-fit:contain; z-index:10005; filter:drop-shadow(0 10px 10px rgba(0,0,0,0.5)); pointer-events:none; transition: width 0.1s, height 0.1s;';
    engine.appendChild(rightGlove);

    document.body.appendChild(engine);

    // --- CONTROLES ---
    function setPose(pose) {
        currentPose = pose;
        let src = 'assets/Match/PosicionAgarre.png';
        let size = '180px';
        if (pose === 'PUNO') { src = 'assets/Match/PosicionPuño.png'; size = '140px'; }
        if (pose === 'ESTIRADA') { src = 'assets/Match/PosicionEstirada.png'; size = '280px'; }

        leftGlove.src = src; leftGlove.style.width = size; leftGlove.style.height = size;
        rightGlove.src = src; rightGlove.style.width = size; rightGlove.style.height = size;

        updateGlovePositions();
    }

    function updateGlovePositions() {
        let offsetX = (currentPose === 'PUNO') ? 3 : (currentPose === 'ESTIRADA' ? 10 : 5);
        leftGlove.style.left = `calc(${mouseX}% - ${offsetX}%)`;
        leftGlove.style.top = `${mouseY}%`;
        rightGlove.style.left = `calc(${mouseX}% + ${offsetX}%)`;
        rightGlove.style.top = `${mouseY}%`;
    }

    engine.addEventListener('mousemove', (e) => {
        const rect = engine.getBoundingClientRect();
        mouseX = ((e.clientX - rect.left) / rect.width) * 100;
        mouseY = ((e.clientY - rect.top) / rect.height) * 100;
        updateGlovePositions();
    });

    engine.addEventListener('mousedown', (e) => {
        if (e.button === 0) setPose('PUNO'); // Izquierdo
        else if (e.button === 2) setPose('ESTIRADA'); // Derecho
    });

    engine.addEventListener('mouseup', () => setPose('AGARRE'));

    // --- MOTOR DE TIROS ---
    let totalShots = 5;
    let currentShot = 0;
    let saves = 0;
    let goalsConceded = 0;

    const shooter = document.createElement('div');
    shooter.style.cssText = 'position:absolute; width:30px; height:70px; background:rgba(0,0,0,0.6); border-radius:15px; top:45%; left:50%; transform:translate(-50%,-50%); z-index:10001; filter:blur(1px); transition:all 0.4s ease; box-shadow:0 0 10px rgba(0,0,0,0.5);';
    engine.appendChild(shooter);

    function updateHUD() {
        shotDisplay.innerText = `Tiro ${Math.min(currentShot + 1, totalShots)} / ${totalShots}`;
        scoreDisplay.innerText = `Goles: ${goalsConceded} | Paradas: ${saves}`;
    }

    function endMatch() {
        engine.remove();

        const teamGoals = goalsConceded;
        const win = saves >= 3; // Parar la mayoría de 5 tiros

        const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
        if (myTeam) {
            if (win) { myTeam.w++; myTeam.pts += 3; }
            else if (teamGoals === saves) { myTeam.d++; myTeam.pts += 1; }
            else { myTeam.l++; }
        }

        p2League.forEach(t => {
            if (!t.name.includes("Tu Equipo")) {
                t.w += Math.floor(Math.random() * 2);
                t.pts = (t.w * 3) + t.d;
            }
        });

        const matchXp = 250 + (win ? 200 : (teamGoals === saves ? 100 : 50)) + (saves * 75);
        const resultTxt = win ? '¡VICTORIA!' : (teamGoals === saves ? 'EMPATE' : 'DERROTA...');

        showNotification(`${resultTxt} Resultado: Paradas ${saves} - ${teamGoals} Goles`, win ? 'success' : (teamGoals === saves ? 'warning' : 'error'), 6000);

        setTimeout(() => {
            openMatchXpDistributor(matchXp, `${resultTxt} Paraste ${saves} tiros y encajaste ${teamGoals}. XP Total: ${matchXp}`);
        }, 1000);

        // Show room content again after engine closes
        document.getElementById('p2-room-content').style.display = 'block';
    }

    function nextShot() {
        if (currentShot >= totalShots) {
            setTimeout(endMatch, 1000);
            return;
        }
        currentShot++;
        updateHUD();

        // Move shooter for next shot
        let startX = 35 + Math.random() * 30; // 35% to 65%
        let startY = 45 + Math.random() * 5;  // 45% to 50%
        shooter.style.left = `${startX}%`;
        shooter.style.top = `${startY}%`;

        setTimeout(() => playScenario(startX, startY), 1000);
    }

    function playScenario(startX, startY) {
        const ball = document.createElement('img');
        ball.src = 'assets/Match/Balon.png';
        ball.onerror = () => { ball.style.display="none"; };
        ball.style.cssText = `position:absolute; top:${startY}%; left:${startX}%; width:20px; height:20px; z-index:10002; transform:translate(-50%,-50%); pointer-events:none; border-radius:50%;`;
        engine.appendChild(ball);

        let type = Math.floor(Math.random() * 3); // 0=Normal, 1=Power, 2=Curve

        let targetX = 10 + Math.random() * 80;
        let targetY = 10 + Math.random() * 80;

        let flightTime = 1300;
        let requiredPose = 'AGARRE';

        if (type === 0) {
            // Tiro Normal
            ball.style.boxShadow = '0 0 20px 8px rgba(255,255,255,0.8)';
            requiredPose = 'AGARRE';
            flightTime = 1300;
        } else if (type === 1) {
            // Tiro Potente (Puños)
            ball.style.boxShadow = '0 0 25px 12px rgba(255,0,0,0.9)';
            requiredPose = 'PUNO';
            flightTime = 700;
        } else if (type === 2) {
            // Tiro con Efecto (Estirada)
            ball.style.boxShadow = '0 0 25px 12px rgba(180,0,255,0.9)';
            requiredPose = 'ESTIRADA';
            flightTime = 1500;
            targetX = Math.random() > 0.5 ? 10 + Math.random()*15 : 75 + Math.random()*15; // Más esquinado
        }

        setTimeout(() => {
            if (type === 2) { // Efecto
                const midX = (targetX > 50) ? 20 : 80;
                ball.style.transition = `all ${flightTime*0.5}ms cubic-bezier(0.1, 0.7, 0.4, 1)`;
                ball.style.top = '10%';
                ball.style.left = `${midX}%`;
                ball.style.width = '70px'; ball.style.height = '70px';

                setTimeout(() => {
                    ball.style.transition = `all ${flightTime*0.5}ms cubic-bezier(0.5, 0, 0.9, 0.2)`;
                    ball.style.top = `${targetY}%`;
                    ball.style.left = `${targetX}%`;
                    ball.style.width = '160px'; ball.style.height = '160px';
                }, flightTime*0.5);
            } else { // Normal/Potente
                ball.style.transition = `all ${flightTime}ms cubic-bezier(0.3, 0, 0.8, 1)`;
                ball.style.top = `${targetY}%`;
                ball.style.left = `${targetX}%`;
                ball.style.width = '160px'; ball.style.height = '160px';
            }
        }, 50);

        // Resolución
        setTimeout(() => {
            const dist = Math.sqrt(Math.pow(mouseX - targetX, 2) + Math.pow(mouseY - targetY, 2));

            let tolerance = 16; 
            if (currentPose === 'ESTIRADA') tolerance = 28;
            if (currentPose === 'PUNO') tolerance = 14;

            if (dist <= tolerance && currentPose === requiredPose) {
                saves++;
                ball.style.transition = 'all 0.2s';
                ball.style.top = '-20%'; 
                showNotification('¡PARADÓN!', 'success', 1000);
            } else {
                goalsConceded++;
                ball.style.transition = 'all 0.2s';
                ball.style.width = '300px'; ball.style.height = '300px';
                showNotification('¡GOL...', 'error', 1000);

                // Efecto temblor pantalla
                let shakeOffset = 0;
                const shaker = setInterval(() => {
                    shakeOffset = shakeOffset === 0 ? 5 : (shakeOffset === 5 ? -5 : 0);
                    engine.style.transform = `translate(${shakeOffset}px, ${shakeOffset}px)`;
                }, 50);
                setTimeout(() => { clearInterval(shaker); engine.style.transform = 'none'; }, 300);
            }

            updateHUD();
            setTimeout(() => {
                ball.remove();
                nextShot();
            }, 800);
        }, flightTime + 50);
    }

    // Empieza el primer tiro tras prepararse
    setTimeout(nextShot, 1500);
};

args.TargetContent:
window.startGKMinigame = function(ourStrength, enemyStrength, winProbability) {
    p2RoomBody.innerHTML = '';

    const detroitUI = document.getElementById('tactics-detroit-overlay');
    if (detroitUI) detroitUI.remove();

    const engine = document.createElement('div');
    engine.id = 'gk-match-engine';
    engine.style.cssText = 'position:fixed; top:0; left:0; width:100vw; height:100vh; background:url("assets/Match/EstadioPortero.jpeg") center/cover, #2a5a2a; z-index:9999; font-family:"Nunito",sans-serif; overflow:hidden; user-select:none; cursor:crosshair;';

    // Evitar menú contextual clic derecho
    engine.oncontextmenu = e => e.preventDefault();

    const hud = document.createElement('div');
    hud.style.cssText = 'position:absolute; top:20px; left:10%; right:10%; display:flex; justify-content:space-between; color:#fff; text-shadow:0 0 5px #000; font-size:1.5rem; font-weight:bold; background:rgba(0,0,0,0.6); padding:10px 20px; border-radius:10px; border:2px solid #00e5ff; z-index:10010; pointer-events:none;';

    const timeDisplay = document.createElement('div');
    timeDisplay.innerText = "00:00";

    const scoreDisplay = document.createElement('div');
    scoreDisplay.innerText = "Goles Encajados: 0 | Paradas: 0";

    hud.appendChild(timeDisplay);
    hud.appendChild(scoreDisplay);
    engine.appendChild(hud);

    const flash = document.createElement('div');
    flash.style.cssText = 'position:absolute; top:0; left:0; width:100%; height:100%; background:#fff; opacity:0; z-index:120; pointer-events:none; transition:opacity 0.2s;';
    engine.appendChild(flash);

    // Instrucciones
    const helpOverlay = document.createElement('div');
    helpOverlay.style.cssText = 'position:absolute; bottom:10px; left:50%; transform:translateX(-50%); color:#fff; background:rgba(0,0,0,0.5); padding:10px; border-radius:10px; text-align:center; pointer-events:none; z-index:110; text-shadow:0 0 5px #000;';
    helpOverlay.innerHTML = '<b>WASD</b>: Caminar | <b>Espacio + WASD</b>: Lanzarse<br><b>Ratón</b>: Mover Manos | <b>Clic Izq</b>: Mano Abierta | <b>Clic Der</b>: Puños';
    engine.appendChild(helpOverlay);

    // --- MOTOR FÍSICO ---

    const gloves = document.createElement('img');
    gloves.src = 'assets/Match/PosicionAgarre.png';
    gloves.onerror = () => { gloves.style.display="none"; };
    gloves.style.cssText = 'position:absolute; top:50%; left:50%; transform:translate(-50%, -50%); width:180px; height:180px; object-fit:contain; z-index:125; filter:drop-shadow(0 10px 10px rgba(0,0,0,0.5)); pointer-events:none; transition: width 0.1s, height 0.1s;';
    engine.appendChild(gloves);

    document.body.appendChild(engine);

    let minute = 0;
    let saves = 0;
    let goalsConceded = 0;
    let matchInterval = null;
    let physicsLoop = null;
    const highlightMinutes = [14, 31, 55, 78, 89];

    // --- CONTROLES ---
    let bodyX = 0; // % displacement
    let bodyY = 0;
    let mouseX = 50; // %
    let mouseY = 50; // %

    let currentPose = 'AGARRE'; // AGARRE, ESTIRADA, PUNO
    let isDiving = false;
    let diveVelocityX = 0;
    let diveVelocityY = 0;

    const keys = { w:false, a:false, s:false, d:false, space:false };

    const keydownHandler = (e) => {
        const k = e.key.toLowerCase();
        if (k === 'w' || k === 'arrowup') keys.w = true;
        if (k === 'a' || k === 'arrowleft') keys.a = true;
        if (k === 's' || k === 'arrowdown') keys.s = true;
        if (k === 'd' || k === 'arrowright') keys.d = true;
        if (e.code === 'Space') keys.space = true;
    };
    const keyupHandler = (e) => {
        const k = e.key.toLowerCase();
        if (k === 'w' || k === 'arrowup') keys.w = false;
        if (k === 'a' || k === 'arrowleft') keys.a = false;
        if (k === 's' || k === 'arrowdown') keys.s = false;
        if (k === 'd' || k === 'arrowright') keys.d = false;
        if (e.code === 'Space') keys.space = false;
    };

    window.addEventListener('keydown', keydownHandler);
    window.addEventListener('keyup', keyupHandler);

    engine.addEventListener('mousemove', (e) => {
        const rect = engine.getBoundingClientRect();
        mouseX = ((e.clientX - rect.left) / rect.width) * 100;
        mouseY = ((e.clientY - rect.top) / rect.height) * 100;
    });

    engine.addEventListener('mousedown', (e) => {
        if (e.button === 0) { // Clic Izquierdo = Estirada
            currentPose = 'ESTIRADA';
            gloves.src = 'assets/Match/PosicionEstirada.png';
            gloves.style.width = '280px';
            gloves.style.height = '180px';
        } else if (e.button === 2) { // Clic Derecho = Puños
            currentPose = 'PUNO';
            gloves.src = 'assets/Match/PosicionPuño.png';
            gloves.style.width = '140px';
            gloves.style.height = '140px';
        }
    });

    engine.addEventListener('mouseup', (e) => {
        currentPose = 'AGARRE';
        gloves.src = 'assets/Match/PosicionAgarre.png';
        gloves.style.width = '180px';
        gloves.style.height = '180px';
    });

    // Bucle Físico (60fps)
    physicsLoop = setInterval(() => {

        // Lógica de Salto (Espacio)
        if (keys.space && !isDiving) {
            let dx = 0; let dy = 0;
            if (keys.w) dy = -1;
            if (keys.s) dy = 1;
            if (keys.a) dx = -1;
            if (keys.d) dx = 1;

            if (dx !== 0 || dy !== 0) {
                isDiving = true;
                diveVelocityX = dx * 8; // Velocidad de estirada
                diveVelocityY = dy * 8;

                engine.style.transition = 'filter 0.2s';
                engine.style.filter = 'blur(2px)';

                setTimeout(() => {
                    diveVelocityX = 0;
                    diveVelocityY = 0;
                    engine.style.filter = 'none';
                }, 400); // 400ms de vuelo

                setTimeout(() => {
                    isDiving = false;
                }, 1200); // Cooldown antes del próximo salto
            }
        }

        // Mover el cuerpo del portero
        if (isDiving) {
            bodyX += diveVelocityX;
            bodyY += diveVelocityY;

            // Límites de la estirada (mucho más amplios)
            bodyX = Math.max(-90, Math.min(90, bodyX));
            bodyY = Math.max(-90, Math.min(90, bodyY));
        } else {
            // Movimiento normal
            if (keys.w) bodyY = Math.max(-30, bodyY - 1.5);
            if (keys.s) bodyY = Math.min(30, bodyY + 1.5);
            if (keys.a) bodyX = Math.max(-40, bodyX - 1.5);
            if (keys.d) bodyX = Math.min(40, bodyX + 1.5);
        }

        // El fondo se mueve en dirección contraria
        engine.style.backgroundPosition = `${50 + (bodyX*0.3)}% ${50 + (bodyY*0.3)}%`;

        // Los guantes son posición del ratón + desplazamiento del cuerpo
        let finalGx = mouseX + bodyX;
        let finalGy = mouseY + bodyY;

        gloves.style.left = `${finalGx}%`;
        gloves.style.top = `${finalGy}%`;

    }, 16);

    function updateHUD() {
        timeDisplay.innerText = `${minute < 10 ? '0':''}${minute}:00`;
        scoreDisplay.innerText = `Goles Encajados: ${goalsConceded} | Paradas: ${saves}`;
    }

    function endMatch() {
        window.removeEventListener('keydown', keydownHandler);
        window.removeEventListener('keyup', keyupHandler);
        clearInterval(physicsLoop);
        engine.remove();

        const teamGoals = Math.floor(Math.random() * 3);
        const win = teamGoals > goalsConceded;

        const myTeam = p2League.find(t => t.name.includes("Tu Equipo"));
        if (myTeam) {
            if (win) { myTeam.w++; myTeam.pts += 3; }
            else if (teamGoals === goalsConceded) { myTeam.d++; myTeam.pts += 1; }
            else { myTeam.l++; }
        }

        p2League.forEach(t => {
            if (!t.name.includes("Tu Equipo")) {
                t.w += Math.floor(Math.random() * 2);
                t.pts = (t.w * 3) + t.d;
            }
        });

        const matchXp = 250 + (win ? 200 : (teamGoals === goalsConceded ? 100 : 50)) + (saves * 75);
        const resultTxt = win ? '¡VICTORIA!' : (teamGoals === goalsConceded ? 'EMPATE' : 'DERROTA...');

        showNotification(`${resultTxt} Resultado: ${teamGoals}-${goalsConceded}. Paradas: ${saves}`, win ? 'success' : (teamGoals===goalsConceded ? 'warning':'error'), 6000);

        setTimeout(() => {
            openMatchXpDistributor(matchXp, `${resultTxt} El equipo metió ${teamGoals} goles, encajaste ${goalsConceded} y paraste ${saves} tiros. XP Total: ${matchXp}`);
        }, 1000);
    }

    function startHighlight() {
        flash.style.opacity = '1';
        setTimeout(() => { flash.style.opacity = '0'; }, 200);

        const alertTxt = document.createElement('div');
        alertTxt.style.cssText = 'position:absolute; top:35%; left:50%; transform:translate(-50%,-50%); font-size:3rem; color:#ff4444; text-shadow:0 0 10px #000, 0 0 20px #ff0000; font-weight:bold; z-index:115; white-space:nowrap; animation: bounce 1s infinite; pointer-events:none;';
        alertTxt.innerText = "¡PELIGRO!";
        engine.appendChild(alertTxt);

        const scenario = Math.floor(Math.random() * 5);

        setTimeout(() => {
            alertTxt.remove();
            playScenario(scenario);
        }, 1000);
    }

    function finishPlay(success, txtWin, txtLose) {
        if (success) {
            saves++; showNotification(txtWin, 'success', 2000);
        } else {
            goalsConceded++; showNotification(txtLose, 'error', 2000);
        }
        setTimeout(resumeMatch, 1000);
    }

    function playScenario(type) {
        let flightTime = 1500;

        const ball = document.createElement('img');
        ball.src = 'assets/Match/Balon.png';
        ball.onerror = () => { ball.style.display="none"; };
        ball.style.cssText = `position:absolute; top:50%; left:50%; width:10px; height:10px; z-index:115; filter:drop-shadow(0 0 10px #000); background:#fff; border-radius:50%; transform:translate(-50%,-50%); pointer-events:none;`;
        engine.appendChild(ball);

        let targetX = 50, targetY = 50;
        let requiredPose = 'ANY';

        if (type === 0) { // TIRO LEJANO
            targetX = 10 + Math.random()*80; 
            targetY = 15 + Math.random()*70;
            requiredPose = 'ESTIRADA';
            flightTime = 1300;
        } else if (type === 1) { // PASE DE LA MUERTE
            targetX = 20 + Math.random()*60;
            targetY = 60 + Math.random()*30;
            requiredPose = 'AGARRE'; 
            flightTime = 900;
        } else if (type === 2) { // CORNER
            targetX = 30 + Math.random()*40;
            targetY = 10 + Math.random()*25; 
            requiredPose = 'PUNO';
            flightTime = 1600;
        } else if (type === 3) { // PENALTI
            targetX = Math.random() > 0.5 ? 15 : 85;
            targetY = 60 + Math.random()*20;
            requiredPose = 'ESTIRADA';
            flightTime = 550; // Súper rápido
        } else if (type === 4) { // FALTA (CURVA)
            targetX = Math.random() > 0.5 ? 20 : 80;
            const midX = targetX === 20 ? 60 : 40; 
            targetY = 15 + Math.random()*20;
            requiredPose = 'ESTIRADA';
            flightTime = 1700;

            // Animación curva en 2 pasos
            setTimeout(() => {
                ball.style.transition = `all ${flightTime*0.5}ms cubic-bezier(0.1, 0.7, 0.4, 1)`;
                ball.style.top = '10%';
                ball.style.left = `${midX}%`;
                ball.style.width = '50px'; ball.style.height = '50px';

                setTimeout(() => {
                    ball.style.transition = `all ${flightTime*0.5}ms cubic-bezier(0.5, 0, 0.9, 0.2)`;
                    ball.style.top = `${targetY}%`;
                    ball.style.left = `${targetX}%`;
                    ball.style.width = '120px'; ball.style.height = '120px';
                }, flightTime*0.5);
            }, 50);
        }

        // Animación recta normal
        if (type !== 4) {
            setTimeout(() => {
                ball.style.transition = `all ${flightTime}ms cubic-bezier(0.3, 0, 0.8, 1)`;
                ball.style.top = `${targetY}%`;
                ball.style.left = `${targetX}%`;
                ball.style.width = '120px';
                ball.style.height = '120px';
            }, 50);
        }

        // Resolución del choque
        setTimeout(() => {
            // Posición final virtual de los guantes
            const gx = mouseX + bodyX;
            const gy = mouseY + bodyY;

            // Distancia euclidiana (%)
            const dist = Math.sqrt(Math.pow(gx - targetX, 2) + Math.pow(gy - targetY, 2));

            // Tolerancia de hitbox según la pose
            let tolerance = 12; // Base (AGARRE)
            if (currentPose === 'ESTIRADA') tolerance = 25; // Más área
            if (currentPose === 'PUNO') tolerance = 15;

            let success = false;
            if (dist <= tolerance) {
                if (requiredPose === 'ANY' || currentPose === requiredPose) {
                    success = true;
                } else if (requiredPose === 'ESTIRADA' && currentPose === 'AGARRE' && dist <= 8) {
                    // Si le da justo en el pecho aunque sea un tiro lejano, la para
                    success = true;
                }
            }

            if (success) {
                ball.style.transition = 'all 0.2s';
                ball.style.top = '-20%'; // Despeje arriba
                finishPlay(true, '¡PARADÓN VITAL!', '');
            } else {
                ball.style.transition = 'all 0.2s';
                ball.style.width = '200px'; ball.style.height = '200px';
                finishPlay(false, '', '¡GOL DEL RIVAL!');
            }

            setTimeout(() => { ball.remove(); }, 500);
        }, flightTime + 50);
    }

    function resumeMatch() {
        updateHUD();
        matchInterval = setInterval(() => {
            minute++;
            updateHUD();

            if (highlightMinutes.includes(minute)) {
                clearInterval(matchInterval);
                startHighlight();
            } else if (minute >= 90) {
                clearInterval(matchInterval);
                endMatch();
            }
        }, 80);
    }

    resumeMatch();
};

