document.addEventListener('DOMContentLoaded', () => {
    // ╔═══════════════════════════════════════════════════════════╗
    // ║  🎮 PREQUEL / MODE SELECTION                              ║
    // ╚═══════════════════════════════════════════════════════════╝
    const prequelScreen = document.getElementById('prequel-selection-screen');
    const btnHokkaido = document.getElementById('btn-select-hokkaido');
    const btnBluelock = document.getElementById('btn-select-bluelock');
    const saveSlotsContainer = document.getElementById('save-slots-container');

    function hidePrequelScreen() {
        if (prequelScreen) {
            prequelScreen.style.opacity = '0';
            prequelScreen.style.transition = 'opacity 0.6s ease';
            setTimeout(() => { prequelScreen.style.display = 'none'; }, 600);
        }
    }

    // Hokkaido mode
    if (btnHokkaido) {
        btnHokkaido.addEventListener('click', () => {
            window.gamePhase = 1; // Furano (Hokkaido)
            hidePrequelScreen();
            const selScreen = document.getElementById('player-selection-screen');
            if (selScreen) selScreen.classList.remove('hidden');
        });
        btnHokkaido.addEventListener('mouseenter', () => { btnHokkaido.style.transform = 'scale(1.05)'; btnHokkaido.style.boxShadow = '0 0 25px rgba(255,255,255,0.5)'; });
        btnHokkaido.addEventListener('mouseleave', () => { btnHokkaido.style.transform = ''; btnHokkaido.style.boxShadow = ''; });
    }

    // Blue Lock mode
    if (btnBluelock) {
        btnBluelock.addEventListener('click', () => {
            window.gamePhase = 2; // Blue Lock
            hidePrequelScreen();
            const cinScreen = document.getElementById('cinematic-screen');
            const selScreen = document.getElementById('player-selection-screen');
            if (cinScreen && !cinScreen.classList.contains('hidden')) {
                // Cinematic is already visible, let it play
            } else if (selScreen) {
                selScreen.classList.remove('hidden');
            }
        });
        btnBluelock.addEventListener('mouseenter', () => { btnBluelock.style.transform = 'scale(1.05)'; btnBluelock.style.boxShadow = '0 0 25px rgba(0,85,255,0.7)'; });
        btnBluelock.addEventListener('mouseleave', () => { btnBluelock.style.transform = ''; btnBluelock.style.boxShadow = ''; });
    }

    // Render save slots
    if (saveSlotsContainer) {
        const saveKey = 'webfutbol_story_save';
        const saved = localStorage.getItem(saveKey);
        if (saved) {
            try {
                const state = JSON.parse(saved);
                const slotDiv = document.createElement('div');
                slotDiv.style.cssText = 'cursor:pointer; background:#1a1a2e; border:2px solid #00e5ff; border-radius:12px; padding:15px 25px; text-align:center; transition:transform 0.2s, box-shadow 0.2s;';
                slotDiv.innerHTML = `
                    <div style="font-family:'Bangers'; font-size:1.3rem; color:#00e5ff; margin-bottom:5px;">📂 Partida Guardada</div>
                    <div style="font-family:'Nunito',sans-serif; color:#aaa; font-size:0.85rem;">Jugador: ${state.myPlayerId || 'Desconocido'}</div>
                `;
                slotDiv.addEventListener('click', () => {
                    hidePrequelScreen();
                    // Small delay to let prequel screen fade
                    setTimeout(() => {
                        if (typeof window.loadGameState === 'function') {
                            window.loadGameState();
                        }
                    }, 700);
                });
                slotDiv.addEventListener('mouseenter', () => { slotDiv.style.transform = 'scale(1.05)'; slotDiv.style.boxShadow = '0 0 20px rgba(0,229,255,0.5)'; });
                slotDiv.addEventListener('mouseleave', () => { slotDiv.style.transform = ''; slotDiv.style.boxShadow = ''; });
                saveSlotsContainer.appendChild(slotDiv);
            } catch(e) { console.error('Error parsing save:', e); }
        }
    }

